mod solution;

fn main() {
    let cases = [
    (r#"n=4 edges=(0,1),(1,2),(2,3),(3,0)"#, r#"true"#),
    (r#"n=3 edges=(0,1),(1,2),(2,0)"#, r#"false"#),
    (r#"
n=3 edges=(0,1),(1,2),(2,0)
"#, r#"false"#),
    (r#"  
n=4 edges=(0,1),(1,2),(2,3),(3,0)
  "#, r#"true"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS bipartite-coloring");
}
